{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"City of Los Angeles Just Cause for Eviction Ordinance (JCO)","requirement":"A landlord may not end a tenancy without a listed just cause and must pay relocation assistance for no-fault evictions (owner move-in, demolition, government order); nonpayment eviction only if owed rent exceeds Fair Market Rent; eviction notices filed with LAHD within three business days.","key_value":"Just cause required; relocation assistance for no-fault evictions","coverage_conditions":"Most City of Los Angeles residential rentals not regulated by the RSO; tenant must have lived in the unit six months or their lease expired; applies to post-October 1, 1978 buildings and single-family dwellings.","applicability":{"built_on_or_before":null,"built_after":"1978-10-01","date_basis":"construction_date","min_units":null,"max_units":null,"owner_dependent":true,"other":"Coverage requires six months' tenancy or expired original lease; applies to single-family dwellings."},"exemptions":"RSO-regulated units; transient hotels, licensed care facilities, fraternity or sorority houses, owner's roommate, certain cooperatives, some non-profit homeless facilities and substance-abuse treatment centers, and some HACLA or government-owned properties.","penalty":null,"effective_date":null,"citation":"City of Los Angeles Just Cause Ordinance (JCO)","quoted_span":"It prohibits terminations of tenancies without just cause and requires relocation assistance for no-fault evictions.","interaction":"The JCO does not regulate rent increases; state AB 1482 may cap rents in buildings older than 15 years.","confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"CA","category":"rent_increase_limits","lifecycle":"enacted","title":"California Tenant Protection Act (AB 1482) annual rent cap","requirement":"Annual rent increases are limited to 5% plus the regional cost-of-living change, or 10%, whichever is lower; for August 1, 2024 through July 31, 2025 the maximum allowable increase is 8.9%.","key_value":"5% + CPI, max 10%; 8.9% for 8/1/2024–7/31/2025","coverage_conditions":"Units older than 15 years on a rolling basis; single-family homes and condominiums exempt only if not owned by a real estate trust, corporation or corporate LLC and the tenant was notified in writing.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":"construction_date","min_units":null,"max_units":null,"owner_dependent":true,"other":"Rolling 15-year cutoff; two-unit property exempt if owner occupied the second unit for the whole tenancy."},"exemptions":"Units constructed within the last 15 years; deed- or regulatory-restricted affordable units; certain dormitories; a two-unit property where the owner occupied the second unit throughout the tenancy; single-family homes and condominiums meeting the ownership and notice conditions; units already subject to the City's RSO.","penalty":null,"effective_date":"2024-08-01","citation":"AB 1482 (Cal. Civ. Code § 1947.12)","quoted_span":"Effective August 1, 2024 to July 31, 2025, the maximum allowable increase is 8.9%.","interaction":"JCO does not regulate rent increases; this state cap applies in buildings older than 15 years.","confidence":0.8,"conflict_flag":false,"conflict_note":null}
